import{d as c,C as t,o as u,c as p,j as a,a as r,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十四章","description":"从大道周遍、生养万物而不为主，理解不自为大与成其大的关系。","frontmatter":{"title":"道德经第三十四章","description":"从大道周遍、生养万物而不为主，理解不自为大与成其大的关系。","category":"guide","aliases":["道德经第三十四章","老子第三十四章","dao de jing chapter 34"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-34.md","filePath":"daoism/dao-de-jing/chapter-34.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-34.md"},y=c({...b,setup(g){const i=[{id:"dao-pervading-all-directions",label:"大道泛兮，其可左右",showLabel:!0,sentences:[["大道",{text:"泛",glossary:"fan"},"兮，其可左右。"]],note:["【白话】大道广泛流行，无所不至，可以向左，也可以向右。句中的方位写它周遍通行，不被固定在某一端。","【王弼注择要】「言道汎滥无所不适，可左右上下周旋而用，则无所不至也。」注以左右上下与周旋解释泛，写作用所至之广。引文汎即本站泛字。","【读法】这里不把泛滥按现代失控灾害义理解；可左右也不是反复改变原则、见风转舵。"]},{id:"giving-life-without-claiming-possession",label:"功成不名有",showLabel:!0,sentences:[["万物",{text:"恃",glossary:"shi"},"之以生而不",{text:"辞",glossary:"ci"},"，功成不",{text:"名有",glossary:"mingyou"},"。"]],note:["【白话】万物依赖大道而生，大道不推辞；事情成就了，也不自称据有这份功业。生养的作用并未变为对万物的占有。","【王弼注择要】「万物皆由道而生，既生而不知其所由。」注从万物由道而生却不觉其所由，说明道的作用不以显名、居功的方式呈现。","【读法】恃在这里作依赖，与为而不恃的自恃分义。辞本页取推辞义，不名有取不自称据有；本站解释与所引王注各自标明。"]},{id:"nurturing-without-dominating",label:"衣养万物而不为主",showLabel:!0,sentences:[[{text:"衣",glossary:"yi"},"养万物而不为主，常",{text:"无欲",glossary:"wuyu"},"，可名于小。"]],note:["【白话】大道覆护、养育万物，却不自居其主，恒常无所贪求，因而可以称它为小。这个小着重不彰显自己、不见其施为的样子。","【王弼注择要】「万物各得所，若道无施于物，故名于小矣。」王弼以各得其所而仿佛不见道的施予，解释何以可名为小。","【读法】衣本页按动词读 yì，取覆盖、使有所衣义，与养相连说明生养。小不是说作用微不足道，不为主也不是拒绝照顾与承担。"]},{id:"all-returning-without-a-master",label:"万物归焉而不为主",showLabel:!0,sentences:[["万物归焉而不为主，可名为大。"]],note:["【白话】万物都归向大道，大道却不自居其主，因此又可以称它为大。大着重万物由之生、归之而各得其所的周遍。","【王弼注择要】「万物皆归之以生。」本页只节引所据录文可明确核读的这句话，以说明万物归焉的生养关系。","【读法】小与大都在不为主的前提下说；不是先谦称自己很小，随后便有权支配万物。所据此处注有语句难明，本页不擅改后再引为古注。"]},{id:"greatness-without-self-aggrandizement",label:"圣人终不为大，故能成其大",showLabel:!0,sentences:[["是以圣人终不为大，故能成其大。"]],note:["【白话】因此，圣人始终不把自己抬为大、不自居其大，反而能成就真正的大。结尾从道的生养不主，转入人的行事与自处。","【王弼注择要】「为大于其细，图难于其易。」王弼在此引向细处、易处着手的行事方式，不把成其大归于外在夸示。","【读法】本站保留是以圣人的句式；所据录文作以其终不自为大故能成其大。不为大取不自为大义，不是拒绝承担重要工作。"]}],n=[{id:"fan",term:"泛",sense:1},{id:"shi",term:"恃",sense:2},{id:"ci",term:"辞",sense:1},{id:"mingyou",term:"名有",sense:1},{id:"yi",term:"衣",sense:1,pinyin:"yì"},{id:"wuyu",term:"无欲",sense:1}];return(f,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十四章",tabindex:"-1"},[r("道德经第三十四章 "),a("a",{class:"header-anchor",href:"#道德经第三十四章","aria-label":'Permalink to "道德经第三十四章"'},"​")],-1)),o(s,{title:"生养万物，为什么仍不自居为主",summary:"本章先说大道周遍可左右，再写万物赖以生长而道不居功、不占有、不主宰。小与大由此并见，最后转到圣人：不自为大，才能成其大。",points:[{label:"先读",text:"泛兮写周遍通行，左右是所至无碍，不是摇摆选边。"},{label:"再辨",text:"不辞、不名有、不为主相贯，辨生养与据有之间的区别。"},{label:"后看",text:"小写不显其施，大写万物归往，结尾再由道转入圣人。"}],hint:"衣养中的衣，本页按动词覆盖、使有所衣理解，读 yì；小与大着重作用与自处，不是体积大小。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"万物恃之以生而不辞，功成不名有。",tone:"作用不化为据有",guide:"有贡献不等于拥有他者，功成也不必总由自己署名占据。"},{text:"衣养万物而不为主，常无欲，可名于小。",tone:"不显其施的小",guide:"从各得其所而不见施予，理解小；生养仍是实在的作用。"},{text:"是以圣人终不为大，故能成其大。",tone:"不自居而能成",guide:"将注意力放在事情和细处，少用自我抬高替代实际成就。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-同一个道为什么既可名小-又可名大" tabindex="-1">象：同一个道为什么既可名小，又可名大？ <a class="header-anchor" href="#象-同一个道为什么既可名小-又可名大" aria-label="Permalink to &quot;象：同一个道为什么既可名小，又可名大？&quot;">​</a></h3><p>当万物各得其所而不见道的施为，可以称小；当万物由之生、归向它，又可以称大。两种称述各指一面，共同前提是道不据有、不自居为主。</p><h3 id="理-不为主和生养之间有什么关系" tabindex="-1">理：不为主和生养之间有什么关系？ <a class="header-anchor" href="#理-不为主和生养之间有什么关系" aria-label="Permalink to &quot;理：不为主和生养之间有什么关系？&quot;">​</a></h3><p>生养写成全万物，不为主写不把这种成全变为私有与支配。若以我养育了你为理由取消对方的自主，生养便转成占有，与本章的意思相离。</p><h3 id="用-有职责的人怎样理解不自为大" tabindex="-1">用：有职责的人怎样理解不自为大？ <a class="header-anchor" href="#用-有职责的人怎样理解不自为大" aria-label="Permalink to &quot;用：有职责的人怎样理解不自为大？&quot;">​</a></h3><p>可以认真承担职务、提供资源与作出决定，同时允许成果属于共同参与的人。对事情负责，与把自己抬成一切成果的唯一来源，应分开判断。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>帮助他人时保留其自主。</strong> 提供资源、指导或照顾时，明确支持的边界，让对方逐渐能自己行动。不要把受过帮助当作永远服从的凭据。</p><p><strong>从细处检验贡献。</strong> 关注具体问题是否解决、他人是否更能工作生活，再谈成果如何呈现。减少自我夸示，不意味着把责任与工作一起隐去。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我是否曾把自己的帮助变成对他人的要求？若成果不再总归于我，我仍愿意把事情做好吗？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留泛，录文作汎；本站「恃之以生」，录文作「恃之而生」。</li><li>本站保留「是以圣人终不为大，故能成其大」，录文作「以其终不自为大故能成其大」。可名于小在所据录文亦作可名於小。</li><li>恃另增依赖义；衣本页按动词读 yì，覆护与养育连读。小、大循王弼不显施予与万物归生理解，不据难明录文补造古注。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，010b–011a</a>。</p><p>字音参考：<a href="https://www.zdic.net/hans/%E8%A1%A3" target="_blank" rel="noreferrer">汉典「衣」动词 yì 及覆盖义</a>。</p>',16))])}}});export{_ as __pageData,y as default};
